create table public.warm_emission_factors (
  model_version text not null default 'WARM v16',
  material text not null,
  pathway_code text not null check (pathway_code in (
    'source_reduction',
    'recycling_post_consumer',
    'landfill_recovery_assumptions',
    'landfill_national_average',
    'landfill_no_recovery',
    'landfill_flaring',
    'landfill_energy_recovery',
    'combustion',
    'composting',
    'wet_digestion_curing',
    'wet_digestion_direct_application',
    'dry_digestion_curing',
    'dry_digestion_direct_application'
  )),
  management_pathway text not null,
  factor_mtco2e_per_short_ton numeric not null,
  factor_unit text not null default 'MTCO2E/short ton',
  source_sheet text not null default 'Summary Data',
  primary key (model_version, material, pathway_code)
);

comment on table public.warm_emission_factors is
  'EPA WARM v16 greenhouse-gas emission factors by material and waste-management pathway. Missing rows indicate the source workbook did not provide a numeric factor.';

alter table public.warm_emission_factors enable row level security;

create policy "Anyone can read WARM emission factors"
  on public.warm_emission_factors
  for select
  using (true);

grant select on public.warm_emission_factors to anon, authenticated;

-- Imported from the EPA WARM v16 Summary Data worksheet.
-- Non-numeric NA/-- cells and workbook calculation/output sheets are not factor records.
on conflict (model_version, material, pathway_code) do nothing;
on conflict (model_version, material, pathway_code) do nothing;
on conflict (model_version, material, pathway_code) do nothing;
on conflict (model_version, material, pathway_code) do nothing;
on conflict (model_version, material, pathway_code) do nothing;
on conflict (model_version, material, pathway_code) do nothing;
